/**
 * SPEC-058: reglas no obvias de la derivación pura del paso del banner
 * (lib/onboardingStep) que complementan la cobertura por componente de
 * InterviewOnboardingBanner.test.tsx — en particular las de la sección
 * «Decisiones asumidas» de la spec: la evaluación se considera resuelta
 * cuando no hay nada que la IA pueda evaluar (sin objetivos o sin
 * transcripción, camino de las marcas manuales SPEC-028), y el banner guía
 * sin bloquear (capturing/oculto → null).
 * Generated by QA Dev agent.
 */
import { describe, expect, it } from 'vitest'
import { deriveOnboardingStep } from '@/lib/onboardingStep'
import type { Interview } from '@/types/domain'

function interview(overrides: Partial<Interview> = {}): Interview {
  return {
    id: 'i-1',
    discoveryId: 'd-1',
    companyId: null,
    contactIds: [],
    interviewGroupId: null,
    templateId: 't-1',
    title: 'Captura',
    status: 'draft',
    scriptMarkdown: null,
    objectives: [],
    wavPath: null,
    transcriptPath: null,
    createdAt: '2026-07-04T10:00:00.000Z',
    updatedAt: '2026-07-04T10:00:00.000Z',
    ...overrides
  }
}

describe('deriveOnboardingStep', () => {
  // SPEC-058 · complemento AC-06/AC-07: en el camino degradado la nota manual
  // cierra el flujo — sin transcripción no hay evaluación IA posible y el
  // paso 6 se salta (las marcas manuales SPEC-028 son la vía)
  it('treats the evaluation as done in the degraded path once the manual note exists', () => {
    const result = deriveOnboardingStep({
      interview: interview({
        scriptMarkdown: '# Guión',
        status: 'recorded',
        objectives: ['Objetivo cero'],
        wavPath: '/tmp/rec.wav',
        transcriptPath: null
      }),
      hasNote: true,
      capturing: false
    })
    expect(result).toEqual({ step: 7, degraded: false })
  })

  // SPEC-058 · complemento AC-07: sin objetivos no hay nada que evaluar
  it('skips step 6 when the interview has no objectives', () => {
    const result = deriveOnboardingStep({
      interview: interview({
        scriptMarkdown: '# Guión',
        status: 'summarized',
        objectives: [],
        wavPath: '/tmp/rec.wav',
        transcriptPath: '/tmp/rec.transcript.json'
      }),
      hasNote: true,
      capturing: false
    })
    expect(result).toEqual({ step: 7, degraded: false })
  })

  // SPEC-058 · complemento AC-05: la grabación asociada manda aunque el
  // status no haya llegado a 'recorded' (wavPath presente)
  it('derives step 5 from wavPath even before the status reflects the recording', () => {
    const result = deriveOnboardingStep({
      interview: interview({
        scriptMarkdown: '# Guión',
        status: 'prepared',
        wavPath: '/tmp/rec.wav',
        transcriptPath: '/tmp/rec.transcript.json'
      }),
      hasNote: false,
      capturing: false
    })
    expect(result).toEqual({ step: 5, degraded: false })
  })

  // SPEC-058 · complemento AC-12/AC-13: capturing y oculto devuelven null
  it('returns null while capturing and when the banner was hidden', () => {
    expect(
      deriveOnboardingStep({ interview: interview(), hasNote: false, capturing: true })
    ).toBeNull()
    expect(
      deriveOnboardingStep({
        interview: interview({ onboardingHiddenAt: '2026-07-27T12:00:00.000Z' }),
        hasNote: false,
        capturing: false
      })
    ).toBeNull()
  })
})
